function Reject-Protocol([string] $ErrorCode = 'MO1307_INPUT') {
    if ($ErrorCode -ceq 'MO1307_FILESYSTEM_BOUNDARY' -and $null -eq $script:n15Failure) {
        try {
            $ProgressPreference = 'SilentlyContinue'
            $n15Frames = @(Get-PSCallStack)
            $n15Caller = if ($n15Frames.Length -gt 1) { [string] $n15Frames[1].FunctionName } else { 'UNKNOWN' }
            $n15Allow = @{
                'Assert-Segment' = @('Value')
                'Assert-Root' = @('Value')
                'Assert-Relative' = @('Value')
                'Open-Native' = @('Path','Directory','InputLeaf','nativeError','handle')
                'Read-Identity' = @('Path','Directory','attributes','length','links','observed','count')
                'Assert-SameIdentity' = @('key','Before','After')
                'Open-Chain' = @('Path','Directory','InputLeaf','index','identity','entries')
                'Assert-NativeAbsent' = @('Path','nativeError','handle')
                'Invoke-Inspection' = @('root','path','status')
                '<ScriptBlock>' = @()
            }
            $n15Locals = [ordered] @{}
            $n15Names = if ($n15Allow.ContainsKey($n15Caller)) { $n15Allow[$n15Caller] } else { @() }
            foreach ($n15Name in $n15Names) {
                $n15Variable = Get-Variable -Name $n15Name -Scope 1 -ErrorAction SilentlyContinue
                if ($null -eq $n15Variable) { continue }
                $n15Value = $n15Variable.Value
                if ($n15Name -ceq 'handle') { $n15Locals['handleIsInvalid'] = [bool] $n15Value.IsInvalid }
                elseif ($n15Name -ceq 'Before' -or $n15Name -ceq 'After') {
                    $n15KeyVariable = Get-Variable -Name key -Scope 1 -ErrorAction SilentlyContinue
                    if ($null -ne $n15KeyVariable -and $n15KeyVariable.Value -cin @('attributes','byteLength','fileId','finalPath','isDirectory','linkCount','volumeSerial')) {
                        $n15Value = $n15Value.([string] $n15KeyVariable.Value)
                        if ($n15Value -is [string] -and $n15Value.Length -gt 240) { $n15Value = $n15Value.Substring(0,120) + '...[TRUNCATED]...' + $n15Value.Substring($n15Value.Length-100) }
                        $n15Locals[$n15Name] = $n15Value
                    }
                }
                elseif ($n15Name -ceq 'identity') { $n15Locals['identityVolumeSerial'] = [string] $n15Value.volumeSerial }
                elseif ($n15Name -ceq 'entries') { $n15Locals['firstVolumeSerial'] = if ($n15Value.Count -gt 0) { [string] $n15Value[0].identity.volumeSerial } else { $null } }
                elseif ($n15Value -is [string]) {
                    if ($n15Value.Length -gt 240) { $n15Locals[$n15Name+'OriginalLength'] = $n15Value.Length; $n15Value = $n15Value.Substring(0,120) + '...[TRUNCATED]...' + $n15Value.Substring($n15Value.Length-100) }
                    $n15Locals[$n15Name] = $n15Value
                }
                elseif ($n15Value -is [bool] -or $n15Value -is [int] -or $n15Value -is [long] -or $n15Value -is [uint32]) { $n15Locals[$n15Name] = $n15Value }
            }
            $n15Stack = @()
            foreach ($n15Frame in $n15Frames | Select-Object -First 6) {
                $n15Function = [string] $n15Frame.FunctionName
                if ($n15Function.Length -gt 64) { $n15Function = $n15Function.Substring(0,64) }
                $n15Stack += ,@($n15Function, [int] $n15Frame.ScriptLineNumber)
            }
            $n15LastErrorBinding = $null
            try {
                $n15Attributes = @($script:native.GetMethod('CreateFileW').GetCustomAttributes([Runtime.InteropServices.DllImportAttribute], $false))
                if ($n15Attributes.Length -eq 1) { $n15LastErrorBinding = [bool] $n15Attributes[0].SetLastError }
            } catch { }
            $n15Record = [ordered] @{
                kind = 'MO1307N15BoundaryFailure'; code = $ErrorCode; caller = $n15Caller
                stack = $n15Stack; locals = $n15Locals
                nativeErrorOwner = if ($n15Locals.Contains('nativeError')) { $n15Caller } else { $null }
                nativeErrorMeaning = 'Original caller-local cached error only; no diagnostic native error read'
                createFileSetLastError = $n15LastErrorBinding
                exceptionConstruction = 'Unchanged System.InvalidOperationException(ErrorCode) throw follows this capture'
                failureOnly = $true
            }
            $n15Text = ($n15Record | ConvertTo-Json -Compress -Depth 6) + [char]10
            $n15Bytes = [Text.UTF8Encoding]::new($false, $true).GetBytes($n15Text)
            if ($n15Bytes.Length -gt 4096) {
                $n15Text = ([ordered] @{ kind='MO1307N15BoundaryCaptureOverflow'; code=$ErrorCode; caller=$n15Caller; stack=$n15Stack; byteLength=$n15Bytes.Length } | ConvertTo-Json -Compress -Depth 4) + [char]10
                $n15Bytes = [Text.UTF8Encoding]::new($false, $true).GetBytes($n15Text)
            }
            if ($n15Bytes.Length -le 4096) { $script:n15Failure = $n15Bytes }
        } catch {
            $script:n15Failure = [Text.Encoding]::ASCII.GetBytes('{"kind":"MO1307N15BoundaryCaptureFailed"}' + [char]10)
        }
    }
    throw [System.InvalidOperationException]::new($ErrorCode)
}
